use serde_json::json;
#[test]fn owner_choice_maps_to_exact_review_answer_not_implicit_approval(){assert_eq!(hs_loop::dshplan::user_reply("Approve")["answers"][0]["selected"],json!(["Approve"]));for text in ["yes","approve","Approve please","Keep planning","Use fixtures",""]{let answer=hs_loop::dshplan::user_reply(text);let mut p=hs_loop::dshplan::PlanSession::default();p.select(true,false);assert!(p.review(&json!({"plan":"# Plan\nSteps"}),Some(&answer)).is_err(),"{text}");assert!(p.active);}}
#[test]fn channel_disconnect_and_dismissal_do_not_approve(){let (send,recv)=std::sync::mpsc::channel();drop(send);assert!(hs_loop::dshplan::receive_review(recv).unwrap_err().contains("dismissed"));let(send,recv)=std::sync::mpsc::channel();send.send(Err("ASK_CANCELLED".into())).unwrap();assert!(hs_loop::dshplan::receive_review(recv).unwrap_err().contains("dismissed"));}
